constraints:
1 ≤ |S|, |P| ≤ 10^{5}

expected time complexity: O(|S|)
expected auxiliary space: O(n) n = len(p) O

standard_solution_code:
class Solution:

	def smallestWindow(self, s, p):
		res = ''
		ans = len(s)
		dic = {}
		for i in p:
			if i in dic:
				dic[i] = dic[i] + 1
			else:
				dic[i] = 1
		count = len(dic)
		i = 0
		start = 0
		j = 0
		while j < len(s):
			if s[j] in dic:
				dic[s[j]] = dic[s[j]] - 1
			else:
				dic[s[j]] = -1
			if dic[s[j]] == 0:
				count = count - 1
			if count == 0:
				while count == 0:
					if ans > j - i + 1:
						ans = j - i + 1
						start = i
					if s[i] in dic:
						dic[s[i]] = dic[s[i]] + 1
					if dic[s[i]] > 0:
						count = count + 1
					i = i + 1
			j = j + 1
		if ans == len(s):
			return '-1'
		else:
			return s[start:start + ans]
